import{_ as p,r as a,o as l,c as o,e as n,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"{% flash %} - October CMS - 4.x","titleTemplate":false,"description":"Twig Tag","frontmatter":{"subtitle":"Twig Tag"},"headers":[{"level":2,"title":"Setting Flash Messages to a Twig Variable","slug":"setting-flash-messages-to-a-twig-variable","link":"#setting-flash-messages-to-a-twig-variable","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/markup/tag/flash.md","filePath":"4.x/markup/tag/flash.md"}'),g={name:"4.x/markup/tag/flash.md"};function u(r,s,k,d,m,h){const t=a("pre-heading"),e=a("post-heading");return l(),o("div",null,[n(t),s[0]||(s[0]=i("h1",null,"{% flash %}",-1)),n(e),s[1]||(s[1]=c(`<div class="custom-block aside"><p>View the <a href="./../../ajax/features/flash-messages.html">Flash Messages article</a> to learn more about using flash messages.</p></div><p>The <code>{% flash %}</code> and <code>{% endflash %}</code> tags will render any flash messages stored in the user session, set by the <code>Flash</code> PHP class. The <code>message</code> variable inside will contain the flash message text and the markup inside will repeat for multiple flash messages.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You can use the <code>type</code> variable that represents the flash message type &amp;mdash; <strong>success</strong>, <strong>error</strong>, <strong>info</strong> or <strong>warning</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You can also specify the <code>type</code> to filter flash messages of a given type. The next example will show only <strong>success</strong> messages, if there is an <strong>error</strong> message it won&#39;t be displayed.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-success<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="setting-flash-messages-to-a-twig-variable"><a href="#setting-flash-messages-to-a-twig-variable" class="header-anchor">#</a> Setting Flash Messages to a Twig Variable</h2><p>In any template you can set the flash messages to a variable with the <code>flash()</code> function. This lets you manipulate the output before display. The function returns an array with one flash message per type.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> messages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The first argument can specify the message type, which returns the message as a string.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> successMessage <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>success<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>If the first argument is set to <strong>all</strong> it will return an array of types, each type is an array of all flash messages.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> allMessages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>all<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../ajax/features/flash-messages.html">Flash Messages</a></li></ul></div>`,16))])}const v=p(g,[["render",u]]);export{f as __pageData,v as default};
